-- Splitter sample groups: Lonavala Trip (8 people), College Outing — Wonderla (6),
-- Flat 302 · Monthly Bills (4 flatmates, July–September).
--
-- 1. Put the email you sign in to Splitter with on the line marked below.
-- 2. Paste this whole file into Supabase → SQL Editor → New query → Run.
-- 3. Refresh the Splitter site: the groups appear in your Groups list.
--
-- Safe to run twice: a sample that already exists in your account is skipped.
-- If the email doesn't match an account, the groups are created without an owner; the result
-- table below then lists a link for each one — open it while signed in to move it into your account.
-- Every expense's shares add up exactly (checked by splitter__save, as when the app saves).

do $$
declare
  v_email text := 'YOUR-SPLITTER-EMAIL@example.com';   -- ← the email you sign in to Splitter with
  v_owner uuid;
  v_group uuid;
  s record;
begin
  select id into v_owner from tharun_expense_splitter_users where email = lower(trim(v_email));
  if v_owner is null then
    raise notice 'No Splitter account with email %. Creating the groups without an owner.', v_email;
  end if;
  for s in select * from (values
    ('Lonavala Trip', $sample${"groupName":"Lonavala Trip","members":[{"id":"m_akhil","name":"Akhil","avatar":"🦁"},{"id":"m_tarun","name":"Tarun","avatar":"😎"},{"id":"m_parthiv","name":"Parthiv"},{"id":"m_dattasai","name":"Dattasai"},{"id":"m_babji","name":"Babji"},{"id":"m_sneha","name":"Sneha","avatar":"🌸"},{"id":"m_karthik","name":"Karthik"},{"id":"m_priya","name":"Priya","avatar":"☕"}],"expenses":[{"id":"e_1","description":"Tempo Traveller rental","category":"Travel","paidBy":"m_karthik","amount":1440000,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_akhil","amount":180000},{"memberId":"m_tarun","amount":180000},{"memberId":"m_parthiv","amount":180000},{"memberId":"m_dattasai","amount":180000},{"memberId":"m_babji","amount":180000},{"memberId":"m_sneha","amount":180000},{"memberId":"m_karthik","amount":180000},{"memberId":"m_priya","amount":180000}],"createdAt":"2026-08-14T01:00:00.000Z"},{"id":"e_2","description":"Breakfast at Ramakant vada pav","category":"Food","paidBy":"m_priya","amount":96000,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_akhil","amount":12000},{"memberId":"m_tarun","amount":12000},{"memberId":"m_parthiv","amount":12000},{"memberId":"m_dattasai","amount":12000},{"memberId":"m_babji","amount":12000},{"memberId":"m_sneha","amount":12000},{"memberId":"m_karthik","amount":12000},{"memberId":"m_priya","amount":12000}],"createdAt":"2026-08-14T03:45:00.000Z"},{"id":"e_3","description":"Villa in Tungarli (2 nights)","category":"Stay","paidBy":"m_akhil","amount":2800000,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_akhil","amount":350000},{"memberId":"m_tarun","amount":350000},{"memberId":"m_parthiv","amount":350000},{"memberId":"m_dattasai","amount":350000},{"memberId":"m_babji","amount":350000},{"memberId":"m_sneha","amount":350000},{"memberId":"m_karthik","amount":350000},{"memberId":"m_priya","amount":350000}],"createdAt":"2026-08-14T07:30:00.000Z"},{"id":"e_4","description":"BBQ dinner at the villa","c