"id":"e_5","description":"Ice cream","category":"Food","paidBy":"m_divya","amount":36000,"splitMode":"exact","splitInput":{},"splits":[{"memberId":"m_rahul","amount":6000},{"memberId":"m_ananya","amount":6000},{"memberId":"m_vikram","amount":12000},{"memberId":"m_divya","amount":6000},{"memberId":"m_harini","amount":6000}],"createdAt":"2026-09-05T10:30:00.000Z"},{"id":"e_6","description":"Photo prints","category":"Shopping","paidBy":"m_harini","amount":45000,"splitMode":"exact","splitInput":{},"splits":[{"memberId":"m_ananya","amount":15000},{"memberId":"m_divya","amount":15000},{"memberId":"m_harini","amount":15000}],"createdAt":"2026-09-05T11:45:00.000Z"},{"id":"e_7","description":"Cab back to campus","category":"Travel","paidBy":"m_vikram","amount":116500,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_rahul","amount":19417},{"memberId":"m_ananya","amount":19417},{"memberId":"m_vikram","amount":19417},{"memberId":"m_divya","amount":19417},{"memberId":"m_sai","amount":19416},{"memberId":"m_harini","amount":19416}],"createdAt":"2026-09-05T13:30:00.000Z"}],"settlements":[{"id":"s_8","from":"m_sai","to":"m_rahul","amount":100000,"note":"UPI","createdAt":"2026-09-06T05:30:00.000Z"}]}$sample$::jsonb),
    ('Flat 302 · Monthly Bills', $sample${"groupName":"Flat 302 · Monthly Bills","members":[{"id":"m_arjun","name":"Arjun","avatar":"🧑‍💻"},{"id":"m_kiran","name":"Kiran"},{"id":"m_nikhil","name":"Nikhil","avatar":"⚽"},{"id":"m_varun","name":"Varun"}],"expenses":[{"id":"e_1","description":"Rent","category":"Bills","paidBy":"m_arjun","amount":3600000,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_arjun","amount":900000},{"memberId":"m_kiran","amount":900000},{"memberId":"m_nikhil","amount":900000},{"memberId":"m_varun","amount":900000}],"createdAt":"2026-07-01T04:30:00.000Z"},{"id":"e_2","description":"Maid salary","category":"Maid","paidBy":"m_varun","amount":400000,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_arjun","amount":100000},{"memberId":"m_kiran","amount":100000},{"memberId":"m_nikhil","amount":100000},{"memberId":"m_varun","amount":100000}],"createdAt":"2026-07-03T12:30:00.000Z"},{"id":"e_3","description":"WiFi (ACT Fibernet)","category":"Bills","paidBy":"m_kiran","amount":99900,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_arjun","amount":24975},{"memberId":"m_kiran","amount":24975},{"memberId":"m_nikhil","amount":24975},{"memberId":"m_varun","amount":24975}],"createdAt":"2026-07-05T03:30:00.000Z"},{"id":"e_4","description":"Electricity bill","category":"Bills","paidBy":"m_nikhil","amount":234000,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_arjun","amount":58500},{"memberId":"m_kiran","amount":58500},{"memberId":"m_nikhil","amount":58500},{"memberId":"m_varun","amount":58500}],"createdAt":"2026-07-10T14:30:00.000Z"},{"id":"e_5","description":"Groceries (BigBasket)","category":"Food","paidBy":"m_arjun","amount":542075,"splitMode":"equal","splitInput":{},"splits":[{"memberId":"m_arjun","amount":135519},{"memberId":"m_kiran","amount":135519},{"memberId":"m_nikhil","amount":135519},{"memberId":"m_varun","amount":135518}],"createdAt":"2026-07-14T13:30:00.000Z"},{"id":"e_6","description":"Rent","catego