000,"note":"July","createdAt":"2026-07-29T03:30:00.000Z"},{"id":"s_20","from":"m_kiran","to":"m_arjun","amount":900000,"note":"August","createdAt":"2026-08-28T04:30:00.000Z"},{"id":"s_21","from":"m_varun","to":"m_arjun","amount":800000,"note":"August","createdAt":"2026-08-30T06:30:00.000Z"}]}$sample$::jsonb)
  ) as t(name, body) loop
    if exists (select 1 from tharun_expense_splitter_groups
               where name = s.name and owner_id is not distinct from v_owner) then
      continue; -- already there
    end if;
    insert into tharun_expense_splitter_groups (name, owner_id) values (s.name, v_owner) returning id into v_group;
    perform splitter__save(v_group, 0, s.body);
  end loop;
end $$;

-- What was created (and a link to open each one on the site)
select g.name,
       (select count(*) from tharun_expense_splitter_members m where m.group_id = g.id) as people,
       (select count(*) from tharun_expense_splitter_expenses e where e.group_id = g.id) as expenses,
       (select round(sum(amount) / 100.0, 2) from tharun_expense_splitter_expenses e where e.group_id = g.id) as total_rupees,
       coalesce(u.email, '(no owner yet — open the link while signed in)') as owner,
       'https://expensersplitter.vercel.app/#g=' || g.token as link
from tharun_expense_splitter_groups g
left join tharun_expense_splitter_users u on u.id = g.owner_id
where g.name in ('Lonavala Trip', 'College Outing — Wonderla', 'Flat 302 · Monthly Bills')
order by g.created_at desc;
